sys_variable_value.value:
(function execute(inputs, outputs) {
// ... code ...

    var bodyText = inputs.raw_body || "";
    var lines = bodyText.split('\n');
    var emailBody = {};

    // 1. Recreate the old ServiceNow automatic name:value parser
    for (var i = 0; i < lines.length; i++) {
        var parts = lines[i].split(':');
        if (parts.length >= 2) {
            // Grab the key (left of colon), trim spaces, convert to lowercase
            var key = parts[0].trim().toLowerCase().replace(/\s+/g, '_'); 
            // Grab the value (right of colon)
            var value = parts.slice(1).join(':').trim(); 
            emailBody[key] = value;
        }
    }

    // 2. Apply your specific logic
    
    // Asset Type Logic
    if (emailBody.asset_type != undefined) {
        var assetType = emailBody.asset_type.toLowerCase();
        if (assetType == 'network gear') {
            outputs.asset_type = 'netgear';
        } else {
            outputs.asset_type = assetType;
        }
    } else {
        outputs.asset_type = "";
    }

    // Consumables Logic
    if (emailBody.consumables != undefined) {
        outputs.consumables = emailBody.consumables.toLowerCase();
    } else if (emailBody.consumable != undefined) {
        outputs.consumables = emailBody.consumable.toLowerCase();
    } else {
         outputs.consumables = "";
    }

    // Priority Logic
    if (emailBody.priority != undefined) {
        outputs.priority = emailBody.priority;
    } else {
        outputs.priority = 3;
    }
    
    // Company Logic
    if (emailBody.company != undefined) {
        outputs.company = emailBody.company;
    } else {
        outputs.company = "";
    }

    // Status
    outputs.status = 'submitted';

})(inputs, outputs);

